BEGIN;
CREATE TABLE IF NOT EXISTS clinical_tenants(id UUID PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS clinical_tenant_members(tenant_id UUID REFERENCES clinical_tenants(id),user_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN('owner','coordinator','evidence_curator','clinical_reviewer','auditor')),active BOOLEAN DEFAULT true,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS clinical_idempotency(actor_id INTEGER,key TEXT,response JSONB NOT NULL,PRIMARY KEY(actor_id,key));
CREATE TABLE IF NOT EXISTS clinical_consents(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES clinical_tenants(id),patient_reference TEXT NOT NULL,scope TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('active','withdrawn','expired')),granted_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,source_reference TEXT NOT NULL,recorded_by INTEGER NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS clinical_evidence_versions(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES clinical_tenants(id),evidence_type TEXT NOT NULL,source_uri TEXT NOT NULL,source_version TEXT NOT NULL,checksum TEXT NOT NULL,terminology_version TEXT NOT NULL,curation_status TEXT NOT NULL CHECK(curation_status IN('pending_review','approved','rejected','superseded')),created_by INTEGER NOT NULL,reviewed_by INTEGER,review_reason TEXT,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(tenant_id,evidence_type,source_version,checksum));
CREATE TABLE IF NOT EXISTS clinical_matching_cases(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES clinical_tenants(id),patient_reference TEXT NOT NULL,minimum_necessary_facts JSONB NOT NULL,state TEXT NOT NULL CHECK(state IN('ready_for_matching','withdrawn','archived')),idempotency_key TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS clinical_explainable_matches(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES clinical_tenants(id),case_id BIGINT NOT NULL REFERENCES clinical_matching_cases(id),trial_reference TEXT NOT NULL,evidence_version_id BIGINT NOT NULL REFERENCES clinical_evidence_versions(id),criteria_results JSONB NOT NULL,contraindications JSONB NOT NULL,score NUMERIC NOT NULL CHECK(score BETWEEN 0 AND 1),state TEXT NOT NULL CHECK(state IN('needs_professional_review','contraindication_review','needs_information','potentially_eligible','not_eligible','withdrawn')),idempotency_key TEXT NOT NULL,created_by INTEGER NOT NULL,reviewed_by INTEGER,review_reason TEXT,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS clinical_governance_audit(id BIGSERIAL PRIMARY KEY,tenant_id UUID REFERENCES clinical_tenants(id),actor_id INTEGER NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,reason TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS clinical_matches_review_idx ON clinical_explainable_matches(tenant_id,state);
COMMIT;
